# Writes the device prompt files: header + _style.txt + body.
import pathlib
here = pathlib.Path(__file__).parent
style = (here / "_style.txt").read_text()
tail = " A portable field device of the triage camp, set up in a hurry this morning beside the wounded: sturdy, practical, clearly carried in and assembled fast. Standalone and perfectly centered on the plain grey background, no characters, the structure crisp, dry and still, every surface plainly lit with no glow."
bodies = {
"dev-lamp-a": "It is a healing lamp on a tall folding tripod of brass legs, standing at the head of a simple wooden cot with a white pillow and a blue-and-cream striped blanket. The tripod's three legs splay wide with brass feet; from its top a short brass arm reaches out over the cot and holds a shallow round brass bowl, rim turned up, lined with sandstone; set flat in the bowl is a round green stone disc carved with the gold Life rune, a sprouting plant. A small deep-blue pennant with the gold eight-pointed star hangs from the tripod's top. At the tripod's foot a square sandstone plate carved with the Life rune sits on the ground, a thin brass cable running up one leg to the bowl. The lamp stands about chest high, the cot knee high.",
"dev-lamp-b": "It is a healing brazier: a wide shallow brass bowl on a sturdy brass tripod, about chest high, the legs braced by a ring and ending in clawed brass feet resting on a low round sandstone base plate. The base plate's top is carved with the gold Life rune, a sprouting plant, on green stone, and three brass ribs rise from it up the legs to the bowl. Inside the bowl sits a cluster of uncut green crystal pieces and a central green stone carved with the Life rune; the bowl's outer face is banded in deep blue enamel with small gold eight-pointed stars. Two brass carrying handles stick out from the bowl's rim. A single plain wooden cot with a white pillow and a blue-and-cream striped blanket stands beside it for scale. The piece is a little taller than it is wide.",
"dev-pylon-a": "It is a mender's pylon standing between two simple wooden cots with white pillows and blue-and-cream striped blankets, set side by side. The pylon is a short square brass post about chest high on a square sandstone foot; set into the ground in front of the foot is a flat square sandstone plate carved with the gold Life rune, a sprouting plant, on green stone. From the post's top two brass arms reach out left and right over the two cots, each ending in a small downward-facing brass dish with a green stone at its centre. A deep-blue band with the gold eight-pointed star wraps the post below the arms. Brass rivets, bolted collars, a folding brace to steady it. The whole piece is wider than it is tall.",
"dev-pylon-b": "It is a mender's pylon: a short brass post about chest high, its lower half a squat sandstone block with a carved green-and-gold Life rune panel, a sprouting plant, on its front face, and at its foot a flat round sandstone plate on the ground carved with the same rune. From the post's top two jointed brass arms fold out like the arms of a lamp stand, reaching wide to either side, each ending in a round brass hood lined with green stone, angled downward. A small brass crank and hinge show how the arms fold away for carrying; a deep-blue enamel collar with the gold eight-pointed star crowns the post. The piece is about twice as wide as it is tall, with the arms spread.",
"dev-frame-a": "It is a portable rune-mat frame on a canvas stretcher: a plain stretcher of two wooden poles and cream canvas, resting on two low folding trestles, and over it a folding brass frame, knee high, of hinged brass bars standing on the ground either side, holding a thin rectangular sandstone plate laid flat just above the canvas. The plate is engraved all over with a grid of small runes and has the gold Life rune, a sprouting plant, on green stone at its centre, its edge trimmed in deep blue with small gold stars. Two braided brass cables run from the frame's corner down to a short sandstone rune stake driven into the ground beside it, the stake's head carved with the Life rune. The piece is long and low, about twice as long as it is wide.",
"dev-frame-b": "It is a portable rune-mat frame: a folding brass frame like a low camp-bed frame on four splayed legs, knee high, carrying a canvas stretcher; hinged above the stretcher on brass arms is a lid-like panel of three sandstone tiles joined by brass hinges, engraved with rune lines and a central green-and-gold Life rune, a sprouting plant, tilted half-open like a cover. A brass box with a deep-blue enamel face and the gold eight-pointed star is bolted to the frame's foot. From it a thick braided brass cable curls across the ground to a tall sandstone rune stake, knee high, pushed into the soil, its top a green stone carved with the Life rune. The piece is longer than it is tall.",
"dev-sheet-a": "It is a sheet of small triage-camp props, six separate objects spread well apart in two rows on the plain grey background with clear empty space around each, every one shown in the same three-quarter view: a wooden bucket with brass hoops beside a shallow brass wash basin; a three-legged wooden stool; a small folding wooden table carrying rolled white bandages, folded cloths and a few glass medicine bottles; a small brass-bound medicine chest with a deep-blue lid and a gold eight-pointed star, its lid closed; a brass oil lantern hanging from a tall slender iron stand with a tripod foot, unlit; a wooden coat rack standing on crossed feet with two deep-blue soldiers' cloaks with gold trim and a brass helmet hanging from its pegs. Each object stands on its own, none touching or overlapping.",
"dev-sheet-b": "It is a sheet of small triage-camp props, six separate objects arranged in a loose grid on the plain grey background with wide empty space between them, all at the same scale and in the same three-quarter view: a stacked pair of wooden buckets and a sandstone wash basin on a low wooden stand; a sturdy camp stool of wood and canvas; a folding camp table with a cream cloth, rolls of bandages, a brass tray of instruments and glass bottles; a small brass medicine chest on short feet, its lid open to show stoppered bottles, the lid's face deep blue with the gold eight-pointed star; a brass lantern on a tall wooden post with a cross foot, unlit; a standing wooden coat rack with a dented brass breastplate and two travel-stained deep-blue cloaks hung on it. No object touches another.",
}
for name, body in bodies.items():
    head = f"Generate one image with your image generation tool, then save it as {name}.png in the current directory. Reply with just the file name.\n\n"
    end = tail if name.startswith("dev-") and "sheet" not in name else " Standalone, on the plain grey background, no characters, every object crisp, dry and still and plainly lit with no glow."
    (here / f"{name}.txt").write_text(head + style + "\n" + body + end + "\n")
print("ok")
